package common

import chisel3._
import chisel3.util._

object Library {

  def ForceZero[T <: Data](x: Valid[T]): Valid[T] = {
    val w = Wire(Valid(chiselTypeOf(x.bits)))
    w.valid := x.valid
    w.bits := Mux(x.valid, x.bits, 0.U.asTypeOf(x.bits))
    w
  }

  def Zip32(sz: UInt, a: UInt, b: UInt): UInt = {
    val result = Wire(UInt(64.W))
    result := 0.U
    switch (sz) {
      is (1.U) {
        result := Cat(
          b(7,0), a(7,0),
          b(15,8), a(15,8),
          b(23,16), a(23,16),
          b(31,24), a(31,24))
      }
      is (2.U) {
        result := Cat(
          b(15,0), a(15,0),
          b(31,16), a(31,16))
      }
      is (4.U) {
        result := Cat(b, a)
      }
    }
    result
  }

  def RotateVectorLeft[T <: Data](in: Vec[ValidIO[T]], shift: UInt): Vec[ValidIO[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      out(i).valid := in(i).valid
      out(i).bits := in(i).bits
    }
    val rotated = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      val srcIdx = (i + shift) % n.U
      rotated(i).valid := out(srcIdx).valid
      rotated(i).bits := out(srcIdx).bits
    }
    rotated
  }

  def RotateVectorRight[T <: Data](in: Vec[ValidIO[T]], shift: UInt): Vec[ValidIO[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      out(i).valid := in(i).valid
      out(i).bits := in(i).bits
    }
    val rotated = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      val srcIdx = ((i - shift) % n.U + n.U) % n.U
      rotated(i).valid := out(srcIdx).valid
      rotated(i).bits := out(srcIdx).bits
    }
    rotated
  }

  def ShiftVectorLeft[T <: Data](in: Vec[ValidIO[T]], shift: UInt): Vec[ValidIO[T]] = {
    val n = in.length
    val result = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    val shiftVal = shift
    for (o <- 0 until n) {
      val wrapped = (o + shiftVal) >= n.U
      val targetIdx = (o + shiftVal) % n.U
      result(targetIdx).valid := Mux(wrapped, false.B, in(o).valid)
      result(targetIdx).bits := Mux(wrapped, 0.U.asTypeOf(chiselTypeOf(in(0).bits)), in(o).bits)
    }
    result
  }

  def ShiftVectorRight[T <: Data](in: Vec[ValidIO[T]], shift: UInt): Vec[ValidIO[T]] = {
    val n = in.length
    val result = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    val shiftVal = shift
    for (o <- 0 until n) {
      val targetIdx = (o.U - shiftVal)
      val wrapped = targetIdx.asSInt < 0.S
      val actualIdx = Wire(UInt(log2Ceil(n).W))
      when (wrapped) {
        actualIdx := (targetIdx + n.U)
      } .otherwise {
        actualIdx := targetIdx
      }
      result(actualIdx).valid := Mux(wrapped, false.B, in(o).valid)
      result(actualIdx).bits := Mux(wrapped, 0.U.asTypeOf(chiselTypeOf(in(0).bits)), in(o).bits)
    }
    result
  }
}

