object Zip32 {
  def apply(sz: UInt, a: UInt, b: UInt): UInt = {
    val result = Wire(UInt(64.W))
    result := Cat(
      Mux(sz === 1.U, b(7,0), Mux(sz === 2.U, b(15,0), b(31,0))),
      Mux(sz === 1.U, a(7,0), Mux(sz === 2.U, a(15,0), a(31,0))),
      Mux(sz === 1.U, b(15,8), Mux(sz === 2.U, b(31,16), 0.U)),
      Mux(sz === 1.U, a(15,8), Mux(sz === 2.U, a(31,16), 0.U)),
      Mux(sz === 1.U, b(23,16), 0.U),
      Mux(sz === 1.U, a(23,16), 0.U),
      Mux(sz === 1.U, b(31,24), 0.U),
      Mux(sz === 1.U, a(31,24), 0.U)
    )
    result
  }
}

object RotateVectorLeft {
  def apply[T <: Data](in: Vec[ValidIO[T]], shift: UInt): Vec[ValidIO[T]] = {
    val n = in.length
    val rotated = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      val srcIdx = Wire(UInt(log2Ceil(n).W))
      srcIdx := Mux((i.U + shift) >= n.U, (i.U + shift) - n.U, i.U + shift)
      rotated(i).valid := in(srcIdx).valid
      rotated(i).bits := in(srcIdx).bits
    }
    rotated
  }
}

object RotateVectorRight {
  def apply[T <: Data](in: Vec[ValidIO[T]], shift: UInt): Vec[ValidIO[T]] = {
    val n = in.length
    val rotated = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      val diff = Wire(SInt(log2Ceil(n).W + 1))
      diff := i.U.asSInt - shift.asSInt
      val srcIdx = Wire(UInt(log2Ceil(n).W))
      srcIdx := Mux(diff < 0.S, (diff + n.S).asUInt, diff.asUInt)
      rotated(i).valid := in(srcIdx).valid
      rotated(i).bits := in(srcIdx).bits
    }
    rotated
  }
}

object ShiftVectorLeft {
  def apply[T <: Data](in: Vec[ValidIO[T]], shift: UInt): Vec[ValidIO[T]] = {
    val n = in.length
    val result = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (o <- 0 until n) {
      val targetIdx = Wire(UInt(log2Ceil(n).W))
      val wrapped = Wire(Bool())
      when ((o.U + shift) >= n.U) {
        targetIdx := (o.U + shift) - n.U
        wrapped := true.B
      } .otherwise {
        targetIdx := o.U + shift
        wrapped := false.B
      }
      result(targetIdx).valid := Mux(wrapped, false.B, in(o).valid)
      result(targetIdx).bits := Mux(wrapped, 0.U.asTypeOf(chiselTypeOf(in(0).bits)), in(o).bits)
    }
    result
