object Zip32 {
  def apply(sz: UInt, a: UInt, b: UInt): UInt = {
    val result = Wire(UInt(64.W))
    result := DontCare
    val words = Cat(b, a)
    val halves = Cat(b(31, 16), a(31, 16), b(15, 0), a(15, 0))
