package common

import chisel3._
import chisel3.util._

class IndexAllocatorShifting(val n: Int) extends Module with IndexAllocator {
  val io = IO(new IndexAllocatorIO(n))
  val bitmap = RegInit(VecInit(Seq.fill(n)(true.B)))
  val head = RegInit(0.U(log2Ceil(n).W))

  val freeBitmap = Wire(Vec(n, Bool()))
  for (i <- 0 until n) {
    when(io.free.fire && io.free.bits === i.U) {
      freeBitmap(i) := true.B
    }.otherwise {
      freeBitmap(i) := bitmap(i)
    }
  }

  val allocBitmap = Wire(Vec(n, Bool()))
  for (i <- 0 until n) {
    when(io.alloc.fire) {
      allocBitmap(i) := freeBitmap(i) && (i.U =/= head)
    }.otherwise {
      allocBitmap(i) := freeBitmap(i)
    }
  }

  bitmap := allocBitmap

  val shiftAmt = Wire(UInt(log2Ceil(n).W))
  shiftAmt := Mux(io.alloc.fire, 1.U, 0.U)

  val nextHead = Wire(UInt(log2Ceil(n).W))
  nextHead := head + shiftAmt
  when(nextHead >= n.U) {
    nextHead := 0.U
  }

  when(io.alloc.fire) {
    head := nextHead
  }

  val anyFree = allocBitmap.reduce(_ || _)
  io.alloc.valid := anyFree
  io.alloc.bits := nextHead
  io.free.ready := !anyFree || bitmap(io.free.bits)
}

trait IndexAllocator {
  val io: IndexAllocatorIO
}

class IndexAllocatorIO(val n: Int) extends Bundle {
  val alloc = Decoupled(UInt(log2Ceil(n).W))
  val free = Flipped(Decoupled(UInt(log2Ceil(n).W)))
}

