package common

import chisel3._
import chisel3.util._

class CoralNPURRArbiter[T <: Data](gen: T, n: Int) extends Module {
  val io = IO(new Bundle {
    val in = Flipped(Vec(n, Decoupled(gen)))
    val out = Decoupled(gen)
    val chosen = Output(UInt(log2Ceil(n).W))
  })

  val grant = RegInit(0.U(log2Ceil(n).W))
  val lastGrant = RegNext(grant, 0.U)
  io.chosen := grant

  val allInvalids = !io.in.map(_.valid).reduce(_ || _)

  when(io.out.fire || allInvalids) {
    var found = false.B
    for (i <- 0 until n) {
      val idx = ((lastGrant + 1.U + i.U) % n.U)
      when(!found && io.in(idx).valid) {
        grant := idx
        found = true.B
      }
    }
  }

  io.out.valid := io.in(grant).valid
  io.out.bits := io.in(grant).bits

  for (i <- 0 until n) {
    io.in(i).ready := (i.U === grant) && io.out.ready
  }
}

