package common

import chisel3._
import chisel3.util._

object Gather {
  def apply[T <: Data](vec: Vec[UInt], regData: Vec[T]): Vec[T] = {
    val n = vec.length
    val out = Wire(Vec(n, chiselTypeOf(regData(0))))
    for (i <- 0 until n) {
      out(i) := 0.U.asTypeOf(chiselTypeOf(regData(0)))
    }
    for (i <- 0 until n) {
      for (j <- 0 until n) {
        when(vec(i) === j.U) {
          out(i) := regData(j)
        }
      }
    }
    out
  }
}

object Scatter {
  def apply[T <: Data](valid: Vec[Bool], idxs: Vec[UInt], regData: Vec[T]): (Vec[T], Vec[Bool], Vec[Bool]) = {
    val n = idxs.length
    val out = Wire(Vec(n, chiselTypeOf(regData(0))))
    val writeMask = Wire(Vec(n, Bool()))
    val idxSelected = Wire(Vec(n, Bool()))

    for (i <- 0 until n) {
      out(i) := 0.U.asTypeOf(chiselTypeOf(regData(0)))
      writeMask(i) := false.B
      idxSelected(i) := false.B
    }

    for (i <- 0 until n) {
      val selected = Wire(Bool())
      selected := false.B
      for (j <- i until n) {
        when(valid(j) && idxs(j) === i.U) {
          selected := true.B
        }
      }
      idxSelected(i) := selected
    }

    var first = true
    for (i <- 0 until n) {
      if (first) {
        when(valid(i) && idxSelected(idxs(i))) {
          out(idxs(i)) := regData(i)
          writeMask(idxs(i)) := true.B
        }
        first = false
      }.elsewhen(true) {
        when(valid(i)) {
          out(idxs(i)) := regData(i)
          writeMask(idxs(i)) := true.B
        }
      }
    }

    (out, writeMask, idxSelected)
  }
}

