class FIFOState[T <: Data](val capacity: Int, t: T) extends Bundle {
  val data = Vec(capacity, t)
  val head = UInt((log2Ceil(capacity + 1)).W)
  val count = UInt((log2Ceil(capacity + 1)).W)

  def invariant(): Bool = {
    head + count <= capacity.U
  }

  def enqueue(in: Vec[T], nValid: UInt): FIFOState[T] = {
    val next = Wire(new FIFOState(capacity, t))
    for (i <- 0 until capacity) {
      next.data(i) := this.data(i)
    }
    next.head := this.head
    next.count := this.count + nValid
    assert(next.count <= capacity.U)
    for (i <- 0 until in.length) {
      val writeIdx = Wire(UInt(log2Ceil(capacity).W))
      val target = this.head + this.count + i.U
      when(target >= capacity.U) {
        writeIdx := target - capacity.U
      }.otherwise {
        writeIdx := target
      }
      when(i.U < nValid) {
        next.data(writeIdx) := in(i)
      }
    }
    next
  }

  def dequeue(n: UInt): FIFOState[T] = {
    val next = Wire(new FIFOState(capacity, t))
    for (i <- 0 until capacity) {
      next.data(i) := this.data(i)
    }
    val nDq = Wire(UInt(log2Ceil(capacity + 1).W))
    nDq := Mux(n > this.count, this.count, n)
    next.count := this.count - nDq
    val newHead = this.head + nDq
    when(newHead >= capacity.U) {
      next.head := newHead - capacity.U
    }.otherwise {
      next.head := newHead
    }
    next
  }

  def flush(): FIFOState[T] = {
    FIFOState.init(capacity, t)
  }

  def peek(n: Int): Vec[T] = {
    val out = Wire(Vec(n, t))
    for (i <- 0 until n) {
      val readIdx = Wire(UInt(log2Ceil(capacity).W))
      val target = this.head + i.U
      when(target >= capacity.U) {
        readIdx := target - capacity.U
      }.otherwise {
        readIdx := target
      }
      out(i) := this.data(readIdx)
    }
    out
  }
}

object FIFOState {
  def init[T <: Data](capacity: Int, t: T): FIFOState[T] = {
    val wire = Wire(new FIFOState(capacity, t))
    for (i <- 0 until capacity) {
      wire.data(i) := 0.U.asTypeOf(t)
    }
    wire.head := 0.U
    wire.count := 0.U
    wire
  }
}

