object Gather {
  def apply[T <: Data](indices: Vec[UInt], data: Vec[T]): Vec[T] = {
    val n = indices.length
    val elemT = chiselTypeOf(data(0))
    val out = Wire(Vec(n, elemT))
    for (i <- 0 until n) {
      out(i) := 0.U.asTypeOf(elemT)
      for (j <- 0 until n) {
        when(indices(i) === j.U) {
          out(i) := data(j)
        }
      }
    }
    out
  }
}

object Scatter {
  def apply[T <: Data](valid: Vec[Bool], idxs: Vec[UInt], regData: Vec[T]): (Vec[T], Vec[Bool], Vec[Bool]) = {
    val n = idxs.length
    val elemT = chiselTypeOf(regData(0))
    val out = Wire(Vec(n, elemT))
    val writeMask = Wire(Vec(n, Bool()))
    val idxSelected = Wire(Vec(n, Bool()))

    for (i <- 0 until n) {
      out(i) := 0.U.asTypeOf(elemT)
      writeMask(i) := false.B
    }

    for (i <- 0 until n) {
      val conflict = Wire(Vec(n, Bool()))
      for (j <- 0 until n) {
        if (j < i) {
          conflict(j) := valid(j) && idxSelected(j) && (idxs(j) === idxs(i))
        } else {
          conflict(j) := false.B
        }
      }
      idxSelected(i) := valid(i) && !conflict.reduce(_ || _)
    }

    for (dest <- 0 until n) {
      val accum = Wire(Vec(n + 1, Bool()))
      val dataChain = Wire(Vec(n + 1, elemT))
      accum(0) := false.B
      dataChain(0) := 0.U.asTypeOf(elemT)
      for (i <- 0 until n) {
        val matchCond = idxSelected(i) && (idxs(i) === dest.U)
        accum(i + 1) := accum(i) || matchCond
        dataChain(i + 1) := Mux(!accum(i) && matchCond, regData(i), dataChain(i))
      }
      writeMask(dest) := accum(n)
      out(dest) := dataChain(n)
    }

    (out, writeMask, idxSelected)
  }
}

