package common

import chisel3._
import chisel3.util._

class Aligner[T <: Data](t: T, n: Int) extends Module {
  val width = t.getWidth
  val io = IO(new Bundle {
    val in = Input(Vec(n, Valid(UInt(width.W))))
    val out = Output(Vec(n, Valid(UInt(width.W))))
  })

  val validBits = VecInit(io.in.map(_.valid.asUInt))

  val prefixSum = Wire(Vec(n, UInt((log2Ceil(n + 1)).W)))
  prefixSum(0) := validBits(0)
  for (i <- 1 until n) {
    prefixSum(i) := prefixSum(i - 1) + validBits(i)
  }

  for (j <- 0 until n) {
    io.out(j).valid := false.B
    io.out(j).bits := 0.U
    for (i <- 0 until n) {
      val targetPos = prefixSum(i) - 1.U
      when(io.in(i).valid && targetPos === j.U) {
        io.out(j).valid := true.B
        io.out(j).bits := io.in(i).bits
      }
    }
  }
}

