package common

import chisel3._
import chisel3.util._

class Fp32 extends Bundle {
  val sign = Bool()
  val exponent = UInt(8.W)
  val mantissa = UInt(23.W)

  def isZero(): Bool = {
    exponent === 0.U && mantissa === 0.U
  }

  def isInf(): Bool = {
    exponent === 255.U && mantissa === 0.U
  }

  def isNan(): Bool = {
    exponent === 255.U && mantissa =/= 0.U
  }
}

object Fp32 {
  def fromWord(word: UInt): Fp32 = {
    val fp = Wire(new Fp32)
    fp.sign := word(31)
    fp.exponent := word(30, 23)
    fp.mantissa := word(22, 0)
    fp
  }

  def fromInteger(int: UInt, signed: Bool): Fp32 = {
    val fp = Wire(new Fp32)
    val absInt = Wire(UInt(32.W))
    val isNeg = Wire(Bool())

    when(signed) {
      isNeg := int(31)
      absInt := Mux(int(31), ~int + 1.U, int)
    }.otherwise {
      isNeg := false.B
      absInt := int
    }

    fp.sign := isNeg

    val leadingZeros = Wire(UInt(6.W))
    leadingZeros := PriorityEncoder(absInt.asBools.reverse)
    val lzCount = Mux(absInt === 0.U, 31.U, leadingZeros)

    val shift = Wire(UInt(5.W))
    shift := Mux(absInt === 0.U, 0.U, 31.U - lzCount)

    val mant = Wire(UInt(23.W))
    when(absInt === 0.U) {
      mant := 0.U
    }.elsewhen(shift <= 23.U) {
      mant := (absInt << (23.U - shift))(22, 0)
    }.otherwise {
      mant := (absInt >> (shift - 23.U))(22, 0)
    }

    fp.mantissa := mant
    fp.exponent := Mux(absInt === 0.U, 0.U, 127.U + shift)
    fp
  }
}

