package common

import chisel3._
import chisel3.util._

class FmaCmd extends Bundle {
  val ina = new Fp32
  val inb = new Fp32
  val inc = new Fp32
}

class FmaState1 extends Bundle {
  val aMan = UInt(24.W)
  val bMan = UInt(24.W)
  val cMan = UInt(24.W)
  val aExp = SInt(10.W)
  val bExp = SInt(10.W)
  val cExp = SInt(10.W)
  val productMan = UInt(48.W)
  val productExp = SInt(10.W)
  val productSign = Bool()
  val cSign = Bool()
  val specialResult = new Fp32
  val isSpecial = Bool()
  val isZeroA = Bool()
  val isZeroB = Bool()
  val isInfA = Bool()
  val isInfB = Bool()
  val isNanA = Bool()
  val isNanB = Bool()
  val isZeroC = Bool()
  val isInfC = Bool()
  val isNanC = Bool()
  val isNormalA = Bool()
  val isNormalB = Bool()
}

class FmaState2 extends Bundle {
  val addMan = UInt(49.W)
  val addExp = SInt(10.W)
  val addSign = Bool()
  val specialResult = new Fp32
  val isSpecial = Bool()
}

object Fma {
  def widenExp(exp: UInt): SInt = {
    val wide = Wire(SInt(10.W))
    wide := Cat(0.S(1.W), exp.asSInt)
    wide
  }

  def FmaStage1(cmd: FmaCmd): FmaState1 = {
    val s1 = Wire(new FmaState1)

    val a = cmd.ina
    val b = cmd.inb
    val c = cmd.inc

    val isZeroA = a.isZero()
    val isZeroB = b.isZero()
    val isInfA = a.isInf()
    val isInfB = b.isInf()
    val isNanA = a.isNan()
    val isNanB = b.isNan()
    val isZeroC = c.isZero()
    val isInfC = c.isInf()
    val isNanC = c.isNan()
    val isNormalA = !isZeroA && !a.exponent.andR
    val isNormalB = !isZeroB && !b.exponent.andR

    s1.isZeroA := isZeroA
    s1.isZeroB := isZeroB
    s1.isInfA := isInfA
    s1.isInfB := isInfB
    s1.isNanA := isNanA
    s1.isNanB := isNanB
    s1.isZeroC := isZeroC
    s1.isInfC := isInfC
    s1.isNanC := isNanC
    s1.isNormalA := isNormalA
    s1.isNormalB := isNormalB

    val special = Wire(new Fp32)
    special.sign := 0.U
    special.exponent := 0.U
    special.mantissa := 0.U

    s1.aMan := Cat(isNormalA, a.mantissa)
    s1.bMan := Cat(isNormalB, b.mantissa)
    val cNormal = !isZeroC && !c.exponent.andR
    s1.cMan := Cat(cNormal, c.mantissa)

    s1.aExp := widenExp(a.exponent)
    s1.bExp := widenExp(b.exponent)
    s1.cExp := widenExp(c.exponent)

    s1.productMan := s1.aMan * s1.bMan

    val rawProductExp = (s1.aExp.asSInt + s1.bExp.asSInt) - 127.S
    val productExpAdj = Wire(SInt(10.W))
    when(s1.productMan(47)) {
      productExpAdj := rawProductExp + 1.S
    }.otherwise {
      productExpAdj := rawProductExp
    }
    s1.productExp := productExpAdj

    s1.productSign := a.sign ^ b.sign
    s1.cSign := c.sign

    val isSpecial = isNanA || isNanB || isNanC ||
      ((isInfA || isInfB) && isInfC && (a.sign ^ b.sign ^ c.sign))

    when(isNanA || isNanB || isNanC) {
      special.sign := 0.U
      special.exponent := 255.U
      special.mantissa := 4194304.U
      s1.isSpecial := true.B
    }.elsewhen((isInfA || isInfB) && isInfC && (a.sign ^ b.sign =/= c.sign)) {
      special.sign := 0.U
      special.exponent := 255.U
      special.mantissa := 4194304.U
      s1.isSpecial := true.B
    }.elsewhen((isInfA || isInfB) && !isInfC) {
      special.sign := a.sign ^ b.sign
      special.exponent := 255.U
      special.mantissa := 0.U
      s1.isSpecial := true.B
    }.elsewhen(isInfC && !isInfA && !isInfB) {
      special.sign := c.sign
      special.exponent := 255.U
      special.mantissa := 0.U
      s1.isSpecial := true.B
    }.elsewhen((isZeroA || isZeroB) && !isNanC) {
      special.sign := (a.sign ^ b.sign) ^ c.sign
      special.exponent := c.exponent
      special.mantissa := c.mantissa
      s1.isSpecial := false.B
    }.otherwise {
      s1.isSpecial := false.B
    }

    s1.specialResult := special
    s1
  }

  def FmaStage2(s1: FmaState1): FmaState2 = {
    val s2 = Wire(new FmaState2)

    when(s1.isSpecial) {
      s2.specialResult := s1.specialResult
      s2.isSpecial := true.B
      s2.addMan := 0.U
      s2.addExp := 0.S
      s2.addSign := false.B
    }.otherwise {
      s2.isSpecial := false.B
      s2.specialResult := 0.U.asTypeOf(new Fp32)

      val productEffective = !(s1.isZeroA || s1.isZeroB)

      val isEffSub = s1.productSign ^ s1.cSign

      val expDiff = Wire(SInt(10.W))
      expDiff := s1.productExp - s1.cExp

      val productManAligned = Wire(UInt(49.W))
      val cManAligned = Wire(UInt(49.W))

      when(expDiff >= 0.S) {
        val shift = Wire(UInt(8.W))
        shift := Mux(expDiff > 48.S, 48.U, expDiff.asUInt)
        cManAligned := (Cat(0.U(1.W), s1.cMan) >> shift).asUInt
        productManAligned := Cat(0.U(1.W), s1.productMan)
        s2.addExp := s1.productExp
      }.otherwise {
        val shift = Wire(UInt(8.W))
        shift := Mux((-expDiff) > 48.S, 48.U, (-expDiff).asUInt)
        productManAligned := (Cat(0.U(1.W), s1.productMan) >> shift).asUInt
        cManAligned := Cat(0.U(1.W), s1.cMan)
        s2.addExp := s1.cExp
      }

      when(isEffSub) {
        s2.addMan := productManAligned - cManAligned
      }.otherwise {
        s2.addMan := productManAligned + cManAligned
      }

      s2.addSign := Mux(s1.productMan >= s1.cMan, s1.productSign, s1.cSign ^ isEffSub)
    }

    s2
  }

  def FmaStage3(s2: FmaState2): Fp32 = {
    val out = Wire(new Fp32)

    when(s2.isSpecial) {
      out := s2.specialResult
    }.elsewhen(s2.addMan === 0.U) {
      out.sign := s2.addSign
      out.exponent := 0.U
      out.mantissa := 0.U
    }.otherwise {
      out.sign := s2.addSign

      val lz = Wire(UInt(6.W))
      lz := PriorityEncoder(s2.addMan.asBools.reverse)
      val lzCount = Mux(s2.addMan(48), 0.U, lz)

      val shiftAmt = Wire(UInt(5.W))
      shiftAmt := Mux(lzCount > 31.U, 31.U, lzCount)

      val normMan = (s2.addMan << shiftAmt)(47, 0)
      val roundBit = normMan(0)
      val guardBit = 0.U

      val normExpUnrounded = s2.addExp - lzCount.asSInt + 1.S

      val roundedManTmp = (normMan >> 1.U).asUInt
      val roundedMan = Wire(UInt(23.W))
      when(roundBit && roundedManTmp(0)) {
        roundedMan := (roundedManTmp(22, 0) + 1.U)(22, 0)
      }.elsewhen(roundBit) {
        roundedMan := roundedManTmp(23, 1)
      }.otherwise {
        roundedMan := roundedManTmp(23, 1)
      }

      val expAfterRound = Wire(SInt(10.W))
      expAfterRound := normExpUnrounded

      when(normExpUnrounded >= 255.S) {
        out.exponent := 255.U
        out.mantissa := 0.U
      }.elsewhen(normExpUnrounded <= 0.S) {
        out.exponent := 0.U
        out.mantissa := 0.U
      }.otherwise {
        out.exponent := normExpUnrounded(7, 0).asUInt
        out.mantissa := roundedMan
      }
    }

    out
  }
}

