class IDiv(len: Int) extends Module {
  val io = IO(new Bundle {
    val req = Flipped(Decoupled(new Bundle {
      val a = UInt(len.W)
      val b = UInt(len.W)
      val signed = Bool()
    }))
    val resp = Decoupled(new Bundle {
      val quotient = UInt(len.W)
      val remainder = UInt(len.W)
    })
  })

  val busy = RegInit(false.B)
  val cnt = RegInit(0.U((log2Ceil(len) + 1).W))
  val aReg = Reg(UInt((len * 2).W))
  val bReg = Reg(UInt(len.W))
  val qReg = Reg(UInt(len.W))
  val sSign = Reg(Bool())
  val aSign = Reg(Bool())
  val bSign = Reg(Bool())

  io.req.ready := !busy
  io.resp.valid := busy && cnt === len.U
  io.resp.bits.quotient := Mux(sSign, ~qReg + 1.U, qReg)
  io.resp.bits.remainder := Mux(aSign, ~aReg(len - 1, 0) + 1.U, aReg(len - 1, 0))

  when(io.req.fire) {
    busy := true.B
    cnt := 0.U
    aSign := io.req.bits.signed && io.req.bits.a(len - 1)
    bSign := io.req.bits.signed && io.req.bits.b(len - 1)
    sSign := (io.req.bits.signed && io.req.bits.a(len - 1)) ^
             (io.req.bits.signed && io.req.bits.b(len - 1))
    aReg := Mux(aSign, Cat(0.U(len.W), ~io.req.bits.a.asUInt + 1.U), Cat(0.U(len.W), io.req.bits.a.asUInt))
    qReg := 0.U
    bReg := Mux(bSign, ~io.req.bits.b.asUInt + 1.U, io.req.bits.b.asUInt)
  }.elsewhen(busy) {
    cnt := cnt + 1.U
    val newA = aReg(len * 2 - 2, 0) ## 0.U(1.W)
    val sub = newA(len * 2 - 1, len) - bReg
    when(!sub(len)) {
      aReg := Cat(sub(len - 1, 0), newA(len - 1, 0))
      qReg := Cat(qReg(len - 2, 0), 1.U(1.W))
    }.otherwise {
      aReg := newA
      qReg := Cat(qReg(len - 2, 0), 0.U(1.W))
    }
    when(cnt === (len - 1).U) {
      busy := false.B
    }
  }
}

