object MathUtil {
  def isPow2(x: BigInt): Boolean = x > 0 && (x & (x - 1)) == 0

  def roundUpPow2(x: Int): Int = {
    var v = x - 1
    v |= v >> 1
    v |= v >> 2
    v |= v >> 4
    v |= v >> 8
    v |= v >> 16
    v + 1
  }
}

