  val allocBitmap = Wire(Vec(n, Bool()))
  for (i <- 0 until n) {
    when(io.alloc.fire) {
      allocBitmap(i) := freeBitmap(i) && (i.U =/= head)
    }.otherwise {
      allocBitmap(i) := freeBitmap(i)
    }
