    when(io.alloc.fire && i.U === firstFree) {
      nextBitmap(i) := false.B
    }.elsewhen(io.free.fire && io.free.bits === i.U) {
      nextBitmap(i) := true.B
    }.otherwise {
      nextBitmap(i) := bitmap(i)
