object Zip32 {
  def apply(sz: UInt, a: UInt, b: UInt): UInt = {
    val result = Wire(UInt(64.W))
    val words = Cat(b, a)
    val halves = Cat(b(31, 16), a(31, 16), b(15, 0), a(15, 0))
    val bytes = Cat(
      b(31, 24), a(31, 24),
      b(23, 16), a(23, 16),
      b(15, 8), a(15, 8),
      b(7, 0), a(7, 0))
    when(sz === 4.U) {
      result := words
    }.elsewhen(sz === 2.U) {
      result := halves
    }.otherwise {
      result := bytes
    }
    result
  }
}

object RotateVectorLeft {
  def apply[T <: Data](in: Vec[ValidIO[T]], shift: UInt): Vec[ValidIO[T]] = {
    val n = in.length
