    for (j <- 0 until n) {
      val srcIdx = Wire(UInt(log2Ceil(n).W))
      val diff = Wire(SInt((log2Ceil(n) + 1).W))
      diff := j.S - shift.asSInt
      when(diff < 0.S) {
