class CircularBufferMulti[T <: Data](t: T, val n: Int, val capacity: Int) extends Module {
  val io = IO(new Bundle {
    val enqValid = Input(UInt((log2Ceil(n + 1)).W))
    val enqData = Input(Vec(n, t))
    val deqReady = Input(UInt((log2Ceil(n + 1)).W))
    val flush = Input(Bool())

    val nEnqueued = Output(UInt((log2Ceil(capacity + 1)).W))
    val dataOut = Output(Vec(n, t))
  })

  val data = Reg(Vec(capacity, t))
  val head = RegInit(0.U(log2Ceil(capacity).W))
  val count = RegInit(0.U((log2Ceil(capacity + 1)).W))

  when(io.flush) {
    head := 0.U
    count := 0.U
  }.otherwise {
    val deqAmt = Mux(io.deqReady > count, count, io.deqReady)
    val oldCount = count
    val oldHead = head

    val newHead = Wire(UInt(log2Ceil(capacity).W))
    val headPlusDeq = oldHead + deqAmt
    when(headPlusDeq >= capacity.U) {
      newHead := headPlusDeq - capacity.U
    }.otherwise {
      newHead := headPlusDeq
    }
    head := newHead
    count := oldCount - deqAmt + io.enqValid

    for (i <- 0 until n) {
      when(i.U < io.enqValid) {
        val wrAddr = Wire(UInt(log2Ceil(capacity).W))
        val target = oldHead + oldCount + i.U
        when(target >= capacity.U) {
          wrAddr := target - capacity.U
        }.otherwise {
          wrAddr := target
        }
        data(wrAddr) := io.enqData(i)
      }
    }
  }

  io.nEnqueued := count

  for (i <- 0 until n) {
    val rdAddr = Wire(UInt(log2Ceil(capacity).W))
    val target = head + i.U
    when(target >= capacity.U) {
      rdAddr := target - capacity.U
    }.otherwise {
      rdAddr := target
    }
    io.dataOut(i) := data(rdAddr)
  }
}

