class Fp32 extends Bundle {
  val sign = Bool()
  val exponent = UInt(8.W)
  val mantissa = UInt(23.W)

  def isZero(): Bool = {
    exponent === 0.U && mantissa === 0.U
  }

  def isInf(): Bool = {
    exponent === 255.U && mantissa === 0.U
  }

  def isNan(): Bool = {
    exponent === 255.U && mantissa =/= 0.U
  }
}

object Fp32 {
  def fromWord(word: UInt): Fp32 = {
    val fp = Wire(new Fp32)
    fp.sign := word(31)
    fp.exponent := word(30, 23)
    fp.mantissa := word(22, 0)
    fp
  }

  def fromInteger(int: UInt, signed: Bool): Fp32 = {
    val fp = Wire(new Fp32)
    val absInt = Wire(UInt(32.W))
    val isNeg = Wire(Bool())

    when(signed) {
      isNeg := int(31)
      absInt := Mux(int(31), ~int + 1.U, int)
    }.otherwise {
      isNeg := false.B
      absInt := int
    }

    fp.sign := isNeg

    val lzVec = Wire(Vec(32, Bool()))
    for (i <- 0 until 32) {
      lzVec(i) := absInt(31 - i)
    }

    val lzRaw = PriorityEncoder(lzVec.asUInt)
    val lz = Mux(absInt === 0.U, 0.U(5.W), lzRaw)

    when(absInt === 0.U) {
      fp.exponent := 0.U
      fp.mantissa := 0.U
    }.otherwise {
      val shift = 31.U - lz
      val mant = Wire(UInt(23.W))
      when(shift <= 23.U) {
        mant := (absInt << (23.U - shift))(22, 0)
      }.otherwise {
        mant := (absInt >> (shift - 23.U))(22, 0)
      }
      fp.mantissa := mant
      fp.exponent := 127.U + shift
    }
    fp
  }
}

