package common

import chisel3._
import chisel3.reflect.DataMirror

object SvGenerationUtils {
  def GenerateInterface(data: Data, prefix: String): String = {
    val flat = GenerateInterfaceFlat(data, prefix)
    flat.mkString(",\n  ")
  }

  def GenerateInterfaceFlat(data: Data, prefix: String): Seq[String] = {
    import scala.collection.mutable.ListBuffer
    val result = ListBuffer[String]()

    def dirStr(d: ActualDirection): String = d match {
      case ActualDirection.Input => "input"
      case ActualDirection.Output => "output"
      case _ => "input"
    }

    def emit(elem: Element, name: String): Unit = {
      val dir = dirStr(DataMirror.directionOf(elem))
      val width = elem.getWidth
      val typ = if (width == 1) "logic" else s"logic [${width - 1}:0]"
      result += s"  $dir $typ ${prefix}_${name}"
    }

    def recurse(d: Data, name: String): Unit = d match {
      case v: Vec[_] =>
        for (i <- 0 until v.length) {
          recurse(v(i), s"${name}_${i}")
        }
      case r: Record =>
        for ((fieldName, field) <- r.elements.toSeq.sortBy(_._1)) {
          recurse(field, s"${name}_${fieldName}")
        }
      case e: Element =>
        emit(e, name)
    }

    recurse(data, prefix)
    result.toSeq.sortBy { s =>
      val dirPart = s.trim.split(" ").head
      dirPart match {
        case "output" => 0
        case "input" => 1
        case _ => 2
      }
    }
  }
}

object GenerateInterface {
  def apply(data: Data, prefix: String): String = {
    SvGenerationUtils.GenerateInterface(data, prefix)
  }
}

