      val width = elem.getWidth
      val typ = if (width == 1) "logic" else s"logic [${width - 1}:0]"
      val line = s"  $dir $typ ${prefix}_${name}"
      if (dir == "output") {
        outputs += line
      } else {
        inputs += line
      }
    }

