        for ((fieldName, field) <- r.elements) {
          recurse(field, s"${name}_${fieldName}")
        }
      case e: Element =>
        emit(e, name)
    }

    recurse(data, prefix)
    outputs.toSeq ++ inputs.toSeq
  }
}

