package common

import chisel3._
import chisel3.util._

class Fp32 extends Bundle {
  val sign = Bool()
  val exponent = UInt(8.W)
  val mantissa = UInt(23.W)

  def isZero(): Bool = {
    exponent === 0.U && mantissa === 0.U
  }

  def isInf(): Bool = {
    exponent === 255.U && mantissa === 0.U
  }

  def isNan(): Bool = {
    exponent === 255.U && mantissa =/= 0.U
  }
}

object Fp32 {
  def fromWord(word: UInt): Fp32 = {
    val fp = Wire(new Fp32)
    fp.sign := word(31)
    fp.exponent := word(30, 23)
    fp.mantissa := word(22, 0)
    fp
  }

  def fromInteger(int: UInt, signed: Bool): Fp32 = {
    val fp = Wire(new Fp32)
    val absInt = Mux(signed && int(31), ~int + 1.U, int)
    val isNeg = signed && int(31)

    fp.sign := isNeg

    val hiZero  = absInt(31, 16) === 0.U(16.W)
    val lo16bits = Mux(hiZero, absInt(15, 0), absInt(31, 16))
    val midZero = lo16bits(15, 8) === 0.U(8.W)
    val lo8bits  = Mux(midZero, lo16bits(7, 0), lo16bits(15, 8))
    val mid2Zero = lo8bits(7, 4) === 0.U(4.W)
    val lo4bits  = Mux(mid2Zero, lo8bits(3, 0), lo8bits(7, 4))
    val mid3Zero = lo4bits(3, 2) === 0.U(2.W)
    val lo2bits  = Mux(mid3Zero, lo4bits(1, 0), lo4bits(3, 2))
    val mid4Zero = lo2bits(1) === 0.U(1.W)

    val lz = Cat(hiZero, midZero, mid2Zero, mid3Zero, mid4Zero)

    when(absInt === 0.U) {
      fp.exponent := 0.U
      fp.mantissa := 0.U
    }.otherwise {
      val shift = 31.U(5.W) - lz
      val mant = Wire(UInt(23.W))
      when(shift <= 23.U(5.W)) {
        mant := (absInt << (23.U(5.W) - shift))(22, 0)
      }.otherwise {
        mant := (absInt >> (shift - 23.U(5.W)))(22, 0)
      }
      fp.mantissa := mant
      fp.exponent := 127.U(8.W) + shift
    }
    fp
  }
}

