    }

    def recurse(d: Data, name: String): Unit = d match {
      case v: Vec[_] =>
        for (i <- 0 until v.length) {
          recurse(v(i), s"${name}_${i}")
        }
      case r: Record =>
        for ((fieldName, field) <- r.elements) {
          if (fieldName == "clock" || fieldName == "reset") {
            // skip
          } else if (name.nonEmpty && fieldName.startsWith(name + "_")) {
            recurse(field, fieldName)
          } else {
            recurse(field, if (name.isEmpty) fieldName else s"${name}_${fieldName}")
          }
        }
      case e: Element =>
        emit(e, name)
    }

    recurse(data, prefix)
    result.toSeq
  }
}

object GenerateInterface {
  def apply(data: Data, prefix: String): String = {
    SvGenerationUtils.GenerateInterface(data, prefix)
  }
}

