package coralnpu

import chisel3._
import chisel3.util._

class Alu(p: Parameters) extends Module {
  val io = IO(new Bundle {
    val req = Flipped(Valid(new Bundle {
      val addr = UInt(8.W)
      val op = AluOp()
    }))
    val rs1 = Flipped(Valid(new Bundle {
      val data = UInt(32.W)
    }))
    val rs2 = Flipped(Valid(new Bundle {
      val data = UInt(32.W)
    }))
    val rd = Valid(new Bundle {
      val addr = UInt(8.W)
      val data = UInt(32.W)
    })
  })

  val busy = RegInit(false.B)
  val result = Reg(UInt(32.W))
  val rdAddr = Reg(UInt(8.W))

  io.rd.valid := busy
  io.rd.bits.addr := rdAddr
  io.rd.bits.data := result

  when(io.req.valid) {
    busy := true.B
    rdAddr := io.req.bits.addr
  }

  when(busy) {
    val op = io.req.bits.op
    val rs1Val = io.rs1.data
    val rs2Val = io.rs2.data

    result := MuxLookup(op, 0.U)(Seq(
      AluOp.SEXTB -> Cat(Fill(24, rs1Val(7)), rs1Val(7, 0)),
      AluOp.SEXTH -> Cat(Fill(16, rs1Val(15)), rs1Val(15, 0)),
      AluOp.ZEXTH -> Cat(0.U(16.W), rs1Val(15, 0)),
      AluOp.CLZ   -> CLZ(rs1Val),
      AluOp.CTZ   -> CTZ(rs1Val),
      AluOp.CPOP  -> PopCount(rs1Val),
      AluOp.ORCB  -> ORCB(rs1Val),
      AluOp.REV8  -> rev8(rs1Val),
      AluOp.XNOR  -> ~(rs1Val ^ rs2Val),
      AluOp.ORN   -> ~(rs1Val | rs2Val),
      AluOp.ANDN  -> rs1Val & (~rs2Val).asUInt,
      AluOp.MAX   -> Mux(rs1Val.asSInt > rs2Val.asSInt, rs1Val, rs2Val),
      AluOp.MAXU  -> Mux(rs1Val > rs2Val, rs1Val, rs2Val),
      AluOp.MIN   -> Mux(rs1Val.asSInt < rs2Val.asSInt, rs1Val, rs2Val),
      AluOp.MINU  -> Mux(rs1Val < rs2Val, rs1Val, rs2Val),
      AluOp.ROL   -> rol(rs1Val, rs2Val(4, 0)),
      AluOp.ROR   -> ror(rs1Val, rs2Val(4, 0)),
    ))
  }

  private def CLZ(x: UInt): UInt = {
    val lz = Wire(UInt(6.W)); lz := 0.U
    for (i <- 0 until 32) { when(x(31 - i)) { lz := i.U } }
    lz
  }
  private def CTZ(x: UInt): UInt = {
    val tz = Wire(UInt(6.W)); tz := 0.U
    for (i <- 0 until 32) { when(x(i)) { tz := i.U } }
    Mux(x === 0.U, 32.U, tz)
  }
  private def ORCB(x: UInt): UInt = {
    Cat(
      Mux(x(31,24).orR, 0xFF.U(8.W), 0.U(8.W)),
      Mux(x(23,16).orR, 0xFF.U(8.W), 0.U(8.W)),
      Mux(x(15,8).orR,  0xFF.U(8.W), 0.U(8.W)),
      Mux(x(7,0).orR,   0xFF.U(8.W), 0.U(8.W)))
  }
  private def rev8(x: UInt): UInt = Cat(x(7,0), x(15,8), x(23,16), x(31,24))
  private def rol(x: UInt, sh: UInt): UInt = (x << sh)(31,0) | (x >> (32.U - sh))(31,0)
  private def ror(x: UInt, sh: UInt): UInt = (x >> sh) | (x << (32.U(6.W) - sh))(31,0)
}

