package coralnpu

import chisel3._

class FRegfile(p: Parameters, numRead: Int, numWrite: Int) extends Module {
  val io = IO(new Bundle {
    val scoreboard = Output(UInt(32.W))
    val scoreboard_set = Input(UInt(32.W))
    val read_ports = Vec(numRead, new Bundle {
      val valid = Input(Bool())
      val addr = Input(UInt(5.W))
      val data = Output(new FpuVal)
    })
    val write_ports = Vec(numWrite, new Bundle {
      val valid = Input(Bool())
      val addr = Input(UInt(5.W))
      val data = Input(new FpuVal)
    })
    val exception = Output(Bool())
  })

  val regs = Reg(Vec(32, new FpuVal))
  val score = RegInit(0.U(32.W))

  when(io.scoreboard_set =/= 0.U) {
    score := score | io.scoreboard_set
  }

  for (i <- 0 until numWrite) {
    when(io.write_ports(i).valid) {
      regs(io.write_ports(i).addr).sign := io.write_ports(i).data.sign
      regs(io.write_ports(i).addr).exponent := io.write_ports(i).data.exponent
      regs(io.write_ports(i).addr).mantissa := io.write_ports(i).data.mantissa
      score := score & ~(1.U << io.write_ports(i).addr)
    }
  }

  for (i <- 0 until numRead) {
    when(io.read_ports(i).valid) {
      io.read_ports(i).data.sign := regs(io.read_ports(i).addr).sign
      io.read_ports(i).data.exponent := regs(io.read_ports(i).addr).exponent
      io.read_ports(i).data.mantissa := regs(io.read_ports(i).addr).mantissa
    }.otherwise {
      io.read_ports(i).data.sign := false.B
      io.read_ports(i).data.exponent := 0.U
      io.read_ports(i).data.mantissa := 0.U
    }
  }

  io.scoreboard := score

  val sameAddr = WireInit(false.B)
  if (numWrite >= 2) {
    sameAddr := io.write_ports(0).valid && io.write_ports(1).valid &&
                io.write_ports(0).addr === io.write_ports(1).addr
  }
  io.exception := sameAddr
}

